    26→// Enhanced responsive breakpoints
    27→const BREAKPOINTS = {
    28→  phone: 0,
    29→  tablet: 768,
    30→  largeTablet: 1024,
    31→  tv: 1440,
    32→};
    33→
    34→const getDeviceType = (screenWidth: number) => {
    35→  if (screenWidth >= BREAKPOINTS.tv) return 'tv';
    36→  if (screenWidth >= BREAKPOINTS.largeTablet) return 'largeTablet';
    37→  if (screenWidth >= BREAKPOINTS.tablet) return 'tablet';
    38→  return 'phone';
    39→};
    40→
    41→// Dynamic poster calculation based on screen width - show 1/4 of next poster
    42→const calculatePosterLayout = (screenWidth: number) => {
    43→  const deviceType = getDeviceType(screenWidth);
    44→
    45→  // Responsive sizing based on device type
    46→  const MIN_POSTER_WIDTH = deviceType === 'tv' ? 180 : deviceType === 'largeTablet' ? 160 : deviceType === 'tablet' ? 140 : 100;
    47→  const MAX_POSTER_WIDTH = deviceType === 'tv' ? 220 : deviceType === 'largeTablet' ? 200 : deviceType === 'tablet' ? 180 : 130;
    48→  const LEFT_PADDING = deviceType === 'tv' ? 32 : deviceType === 'largeTablet' ? 28 : deviceType === 'tablet' ? 24 : 16;
    49→  const SPACING = deviceType === 'tv' ? 12 : deviceType === 'largeTablet' ? 10 : deviceType === 'tablet' ? 8 : 8;
    50→
    51→  // Calculate available width for posters (reserve space for left padding)
    52→  const availableWidth = screenWidth - LEFT_PADDING;
    53→
    54→  // Try different numbers of full posters to find the best fit
    55→  let bestLayout = {
    56→    numFullPosters: 3,
    57→    posterWidth: deviceType === 'tv' ? 200 : deviceType === 'largeTablet' ? 180 : deviceType === 'tablet' ? 160 : 120
    58→  };
    59→
    60→  for (let n = 3; n <= 6; n++) {
    61→    // Calculate poster width needed for N full posters + 0.25 partial poster
    62→    // Formula: N * posterWidth + (N-1) * spacing + 0.25 * posterWidth = availableWidth - rightPadding
    63→    // Simplified: posterWidth * (N + 0.25) + (N-1) * spacing = availableWidth - rightPadding
    64→    // We'll use minimal right padding (8px) to maximize space
    65→    const usableWidth = availableWidth - 8;
    66→    const posterWidth = (usableWidth - (n - 1) * SPACING) / (n + 0.25);
    67→
    68→    if (posterWidth >= MIN_POSTER_WIDTH && posterWidth <= MAX_POSTER_WIDTH) {
    69→      bestLayout = { numFullPosters: n, posterWidth };
    70→    }
    71→  }
    72→
    73→  return {
    74→    numFullPosters: bestLayout.numFullPosters,
    75→    posterWidth: bestLayout.posterWidth,
    76→    spacing: SPACING,
    77→    partialPosterWidth: bestLayout.posterWidth * 0.25 // 1/4 of next poster
    78→  };
    79→};
    80→
    81→const posterLayout = calculatePosterLayout(width);
    82→const POSTER_WIDTH = posterLayout.posterWidth;
