  1974→      // Check if this content was recently scrobbled (to prevent duplicates from component remounts)
  1975→      if (this.isRecentlyScrobbled(contentData)) {
  1976→        logger.log(`[TraktService] Content was recently scrobbled, skipping start: ${contentData.title}`);
  1977→        return true;
  1978→      }
  1979→
  1980→      // ENHANCED PROTECTION: Check if we recently stopped this content with high progress
  1981→      // This prevents restarting sessions for content that was just completed
  1982→      const lastStopTime = this.lastStopCalls.get(watchingKey);
  1983→      if (lastStopTime && (Date.now() - lastStopTime) < 30000) { // 30 seconds
  1984→        logger.log(`[TraktService] Recently stopped this content (${((Date.now() - lastStopTime) / 1000).toFixed(1)}s ago), preventing restart: ${contentData.title}`);
  1985→        return true;
  1986→      }
  1987→
  1988→      // Debug log removed to reduce terminal noise
  1989→
  1990→      // Only start if not already watching this content
  1991→      if (this.currentlyWatching.has(watchingKey)) {
  1992→        logger.log(`[TraktService] Already watching this content, skipping start: ${contentData.title}`);
  1993→        return true; // Already started
  1994→      }
  1995→
  1996→      const result = await this.queueRequest(async () => {
  1997→        return await this.startWatching(contentData, progress);
